('pmbrmbe_0069', 'pmbrmbe', '0069', '69', 'PMBR Early Bird MBE 2007', 'Torts', '69', '', 'Oscar was injured in a taxi crash caused by a drunk driver.', '(A) Taxi company is strictly liable.', '(B) Taxi company is liable if driver acted in scope of employment.', '(C) Taxi company is not liable unless negligent in hiring.', '(D) Taxi company is not liable if Oscar was not seatbelted.', 'B', '', 'pmbrmbe_0069', 0, NULL),
('pmbrmbe_0070', 'pmbrmbe', '0070', '70', 'PMBR Early Bird MBE 2007', 'Torts', '70', '', 'Sandy, a mail carrier, was bitten by a dog while delivering mail.', '(A) Owner is strictly liable.', '(B) Owner is liable only if dog had vicious propensities.', '(C) Owner is not liable to trespassers.', '(D) Owner is not liable if Sandy provoked dog.', 'A', '', 'pmbrmbe_0070', 0, NULL),
('pmbrmbe_0071', 'pmbrmbe', '0071', '71', 'PMBR Early Bird MBE 2007', 'Torts', '71', '', 'Frank, a passenger, sued driver for injuries from reckless driving.', '(A) Frank can recover unless he assumed risk.', '(B) Frank is strictly liable.', '(C) Frank cannot recover if no seatbelt.', '(D) Frank cannot recover if not paying passenger.', 'A', '', 'pmbrmbe_0071', 0, NULL),
('pmbrmbe_0072', 'pmbrmbe', '0072', '72', 'PMBR Early Bird MBE 2007', 'Torts', '72', '', 'Lynn, a nurse, was stuck by a used needle improperly discarded by a doctor.', '(A) Doctor is strictly liable.', '(B) Doctor is liable for negligence.', '(C) Doctor is not liable if nurse was careless.', '(D) Doctor is not liable unless intentional.', 'B', '', 'pmbrmbe_0072', 0, NULL),
('pmbrmbe_0073', 'pmbrmbe', '0073', '73', 'PMBR Early Bird MBE 2007', 'Torts', '73', '', 'Mary’s car struck a cow on the highway, owner knew fence was broken.', '(A) Owner is strictly liable.', '(B) Owner is not liable unless negligent.', '(C) Owner is liable if fence was knowingly broken.', '(D) Owner is not liable.', 'C', '', 'pmbrmbe_0073', 0, NULL),
